set -u
export DEBIAN_FRONTEND=noninteractive
tma_pkg_remove() { for p in "$@"; do
  if command -v dnf >/dev/null 2>&1; then dnf -y remove "$p";
  elif command -v yum >/dev/null 2>&1; then yum -y remove "$p";
  elif command -v apt-get >/dev/null 2>&1; then apt-get -y purge "$p";
  elif command -v zypper >/dev/null 2>&1; then zypper -n remove "$p"; fi; done; }
tma_pkg_install() { for p in "$@"; do
  if command -v dnf >/dev/null 2>&1; then dnf -y install "$p";
  elif command -v yum >/dev/null 2>&1; then yum -y install "$p";
  elif command -v apt-get >/dev/null 2>&1; then apt-get -y install "$p";
  elif command -v zypper >/dev/null 2>&1; then zypper -n install "$p"; fi; done; }
tma_svc_off() { for u in "$@"; do systemctl stop "$u" 2>/dev/null; systemctl mask "$u" 2>/dev/null; done; return 0; }
findmnt -kn /tmp >/dev/null 2>&1 && exit 0
if ! grep -qE '^[^#][^[:space:]]*[[:space:]]+/tmp[[:space:]]' /etc/fstab; then
  cp -a /etc/fstab /etc/fstab.tmaegis.bak.$(date +%Y%m%d%H%M%S)
  echo 'tmpfs /tmp tmpfs defaults,rw,nosuid,nodev,noexec,relatime 0 0' >> /etc/fstab
fi
systemctl unmask tmp.mount 2>/dev/null; systemctl daemon-reload 2>/dev/null
mount /tmp 2>/dev/null || mount -t tmpfs -o rw,nosuid,nodev,noexec,relatime tmpfs /tmp; true

set -u
export DEBIAN_FRONTEND=noninteractive
tma_pkg_remove() { for p in "$@"; do
  if command -v dnf >/dev/null 2>&1; then dnf -y remove "$p";
  elif command -v yum >/dev/null 2>&1; then yum -y remove "$p";
  elif command -v apt-get >/dev/null 2>&1; then apt-get -y purge "$p";
  elif command -v zypper >/dev/null 2>&1; then zypper -n remove "$p"; fi; done; }
tma_pkg_install() { for p in "$@"; do
  if command -v dnf >/dev/null 2>&1; then dnf -y install "$p";
  elif command -v yum >/dev/null 2>&1; then yum -y install "$p";
  elif command -v apt-get >/dev/null 2>&1; then apt-get -y install "$p";
  elif command -v zypper >/dev/null 2>&1; then zypper -n install "$p"; fi; done; }
tma_svc_off() { for u in "$@"; do systemctl stop "$u" 2>/dev/null; systemctl mask "$u" 2>/dev/null; done; return 0; }
p=/tmp; o=nodev
findmnt -kn "$p" >/dev/null 2>&1 || exit 0
if grep -qE "^[^#][^[:space:]]*[[:space:]]+$p[[:space:]]" /etc/fstab 2>/dev/null; then
  awk -v p="$p" -v o="$o" '$0 !~ /^#/ && $2==p { n=split($4,a,","); f=0; for(i=1;i<=n;i++) if(a[i]==o) f=1; if(!f) $4=$4","o } {print}' OFS='\t' /etc/fstab > /etc/fstab.tma && cat /etc/fstab.tma > /etc/fstab && rm -f /etc/fstab.tma
fi
mount -o "remount,$o" "$p" 2>/dev/null || true; true

