mkdir -p /etc/security/limits.d
for f in /etc/security/limits.conf /etc/security/limits.d/*.conf; do [ -f "$f" ] && sed -ri '/^\s*[^#[:space:]][^#]*\s+hard\s+core\s+([1-9]|unlimited)/ s/^/# /' "$f"; done
grep -qsE '^\s*\*\s+hard\s+core\s+0\b' /etc/security/limits.conf /etc/security/limits.d/*.conf || echo '* hard core 0' > /etc/security/limits.d/60-tmaegis-core.conf
