  mp=$(readlink -f "$(dirname "$w")/device/driver/module" 2>/dev/null); [ -e "$mp" ] && basename "$mp"; done | sort -u)
mkdir -p /etc/modprobe.d
for mn in $mods; do
  printf 'install %s /bin/false\nblacklist %s\n' "$mn" "$mn" > "/etc/modprobe.d/60-tmaegis-$mn.conf"
  modprobe -r "$mn" 2>/dev/null; rmmod "$mn" 2>/dev/null
done
command -v nmcli >/dev/null 2>&1 && nmcli radio all off 2>/dev/null
true

